#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Writes the shared cases every otel-muzzle package's tests check.

ratio_vectors.json: a trace is verbose when trace-id bytes 12-15 (the last 8 hex characters), read as a big-endian
unsigned 32-bit integer, are below floor(ratio * 2**32).

ratio_env_vectors.json: how OTEL_MUZZLE_VERBOSE_RATIO is read. Surrounding ASCII whitespace (space, tab, LF, VT, FF,
CR) is ignored, and empty means the default without a warning. Otherwise the value must match ENV_GRAMMAR (a plain
decimal number in ASCII digits) and lie within [0, 1]; anything else logs a warning and means the default.

The output is deterministic: rerun this script after changing it and commit all three files.
"""

import json
import math
import random
import re
from pathlib import Path

RATIOS = [0.0, 0.1, 0.25, 1 / 3, 0.5, 1.0]


def bound(ratio: float) -> int:
    return math.floor(ratio * 2**32)


def trace_id(high: bytes, low: int) -> str:
    """12 leading bytes, then bytes 12-15 as the big-endian uint32 `low`."""
    return high.hex() + f"{low:08x}"


def main() -> None:
    rng = random.Random(20261107)
    ids = []

    def add(low: int, high: bytes | None = None) -> None:
        ids.append(trace_id(high if high is not None else rng.randbytes(12), low))

    # Both ends of the range, and every ratio's boundary from both sides.
    for low in (0, 1, 0x7FFFFFFF, 0x80000000, 0xFFFFFFFE, 0xFFFFFFFF):
        add(low)
    for ratio in RATIOS[1:-1]:
        add(bound(ratio) - 1)
        add(bound(ratio))
    # Ids from other tracing systems. Their leading bytes are not random; bytes 12-15 are.
    add(0xFFFFFFF0, bytes(4) + rng.randbytes(8))  # zero bytes 0-3
    add(0x00000010, bytes(4) + rng.randbytes(8))
    add(0xFFFFFFF0, rng.randbytes(4) + bytes(4) + rng.randbytes(4))  # Datadog 128-bit: seconds, 4 zero bytes, random
    add(0x00000010, rng.randbytes(4) + bytes(4) + rng.randbytes(4))
    add(0xFFFFFFF0, bytes(8) + rng.randbytes(4))  # a 64-bit B3 or Jaeger id, zero-padded to 128 bits
    add(0x00000010, bytes(8) + rng.randbytes(4))
    add(0xC0000000, bytes.fromhex("5f2b7a10") + rng.randbytes(8))  # X-Ray: epoch seconds, then 96 random bits
    # Random ids.
    for _ in range(6):
        add(rng.getrandbits(32))

    cases = [
        {"trace_id": tid, "ratio": ratio, "verbose": int(tid[24:], 16) < bound(ratio)}
        for tid in ids
        for ratio in RATIOS
    ]
    doc = {
        "description": "otel-muzzle ratio selection: a trace is verbose when trace-id bytes 12-15 (the last 8 hex "
        "characters), read as a big-endian uint32, are below floor(ratio * 2**32). Every package's tests check "
        "these cases. Generated by generate_ratio_vectors.py.",
        "cases": cases,
    }
    lines = ['{', f' "description": {json.dumps(doc["description"])},', ' "cases": [']
    lines += [f"  {json.dumps(case)}{',' if i < len(cases) - 1 else ''}" for i, case in enumerate(cases)]
    lines += [" ]", "}", ""]
    Path(__file__).with_name("ratio_vectors.json").write_text("\n".join(lines))
    write_env_vectors()


DEFAULT_RATIO = 0.1
ENV_GRAMMAR = r"[+-]?([0-9]+(\.[0-9]+)?|\.[0-9]+)([eE][+-]?[0-9]+)?"
ENV_INPUTS = [
    # Accepted.
    "0", "1", "0.5", "0.1", ".5", "+.5", "+0.5", "-0", "0.25", "1e-1", "1E0", "5e-1", "1e-400", "0.000000001",
    " 0.5 ", "\t0.25\n", "\v0.3\f", "\r1\r",
    # Empty: the default, without a warning.
    "", "   ", "\t\n",
    # Invalid: a warning, then the default.
    "1.", "0.", "5.", "-0.1", "1.0000001", "2", "1e400", "abc", "0.1 0.2", "0.5,", "1/2", "10%",
    "0x1", "0x0", "0x1p-1", "1_0", "0.2_5", "nan", "NaN", "inf", "-inf", "Infinity",
    "0.5\u00a0", "\ufeff0.5", "\u0660.\u0665", "\uff10.\uff15",
]


def read_env_ratio(raw: str) -> tuple[float, bool]:
    """The reference reading: (ratio, warns)."""
    stripped = raw.strip(" \t\n\v\f\r")
    if stripped == "":
        return DEFAULT_RATIO, False
    if re.fullmatch(ENV_GRAMMAR, stripped):
        ratio = float(stripped)
        if 0.0 <= ratio <= 1.0:
            return ratio, False
    return DEFAULT_RATIO, True


def write_env_vectors() -> None:
    cases = []
    for raw in ENV_INPUTS:
        ratio, warns = read_env_ratio(raw)
        cases.append({"raw": raw, "ratio": ratio, "warns": warns})
    description = (
        "How every otel-muzzle package reads OTEL_MUZZLE_VERBOSE_RATIO. Surrounding ASCII whitespace (space, tab, LF, "
        "VT, FF, CR) is ignored, and an empty value means 0.1 without a warning. Otherwise the value must fully match "
        f"{ENV_GRAMMAR} and lie within [0, 1]; anything else logs a warning naming the variable and the value, and "
        "means 0.1. Generated by generate_ratio_vectors.py."
    )
    lines = ["{", f" \"description\": {json.dumps(description)},", " \"grammar\": " + json.dumps(ENV_GRAMMAR) + ",",
             " \"cases\": ["]
    lines += [f"  {json.dumps(case)}{',' if i < len(cases) - 1 else ''}" for i, case in enumerate(cases)]
    lines += [" ]", "}", ""]
    Path(__file__).with_name("ratio_env_vectors.json").write_text("\n".join(lines))


if __name__ == "__main__":
    main()
